import {mount,Canvas,View,Animated,createAnimatedValue,cleanup,Easing} from "nsh";
function App(){const r=createAnimatedValue(3);const loop=Animated.loop(Animated.timing(r,{toValue:12,duration:1400,easing:Easing.linear}));loop.start();cleanup(()=>loop.stop());return <View style={{flex:1,padding:30,backgroundColor:"#fff"}}><Canvas style={{width:400,height:120}} draw={cx=>{cx.strokeStyle="#269970";cx.beginPath();cx.moveTo(0,60);for(let i=0;i<10000;i++)cx.lineTo(i*0.036,60+30*Math.sin(i*0.006));cx.stroke();cx.fillStyle="#dc2f65";cx.beginPath();cx.arc(360,60,r,0,Math.PI*2);cx.fill();}}/></View>;}mount(App);
